  const [addresses, setAddresses] = useState(initialAddresses); const [selectedAddressId, setSelectedAddressId] = useState('home'); const [addressOpen, setAddressOpen] = useState(false); const [editingId, setEditingId] = useState(null); const [voucherCode, setVoucherCode] = useState(''); const [selectedVoucher, setSelectedVoucher] = useState(null); const [points, setPoints] = useState(0); const [notice, setNotice] = useState('');
  const selectedAddress = addresses.find(address => address.id === selectedAddressId) || addresses[0]; const maxPoints = 5000; const eligibleVouchers = [{ id: 'MLAND100', code: 'MLAND100', title: 'Giảm 100.000 ₫ cho đơn từ 2.000.000 ₫', description: 'Ưu đãi sản phẩm · còn hiệu lực' }, { id: 'SHIP30', code: 'SHIP30', title: 'Giảm 30.000 ₫ phí vận chuyển', description: 'Ưu đãi vận chuyển · áp dụng theo từng đơn chi nhánh' }];
  const formatAddress = address => `${address.street}, ${address.ward}, ${address.district}, ${address.province}`;
  const saveAddress = event => { event.preventDefault(); const data = new FormData(event.currentTarget); const next = { id: editingId === 'new' ? `address-${Date.now()}` : editingId, name: data.get('name'), phone: data.get('phone'), street: data.get('street'), ward: data.get('ward'), district: data.get('district'), province: data.get('province'), tag: data.get('tag'), isDefault: data.get('isDefault') === 'on' }; setAddresses(current => { const without = current.map(address => next.isDefault ? { ...address, isDefault: false } : address).filter(address => address.id !== next.id); return [...without, next]; }); setSelectedAddressId(next.id); setEditingId(null); };
  const AddressForm = () => { const current = addresses.find(address => address.id === editingId) || { name: '', phone: '', street: '', ward: '', district: '', province: 'Hà Nội', tag: 'Nhà riêng', isDefault: false }; return <form className="address-editor" onSubmit={saveAddress}><div className="address-sheet-head"><div><p className="eyebrow">SỔ ĐỊA CHỈ</p><h2>{editingId === 'new' ? 'Thêm địa chỉ mới' : 'Sửa địa chỉ'}</h2></div><button className="text-button" type="button" onClick={() => setEditingId(null)}>Đóng</button></div><div className="address-form-grid"><label>Họ và tên<input name="name" defaultValue={current.name} required /></label><label>Số điện thoại<input name="phone" defaultValue={current.phone} required /></label><label className="wide-field">Số nhà, tên đường<input name="street" defaultValue={current.street} required /></label><label>Phường/Xã<input name="ward" defaultValue={current.ward} required /></label><label>Quận/Huyện<input name="district" defaultValue={current.district} required /></label><label>Tỉnh/Thành phố<input name="province" defaultValue={current.province} required /></label><label>Loại địa chỉ<select name="tag" defaultValue={current.tag}><option>Nhà riêng</option><option>Văn phòng</option></select></label></div><label className="default-toggle"><input name="isDefault" type="checkbox" defaultChecked={current.isDefault} /> Đặt làm địa chỉ mặc định</label><div className="actions"><button className="button primary" type="submit">Hoàn thành</button>{editingId !== 'new' && !current.isDefault && <button className="button outline" type="button" onClick={() => { setAddresses(items => items.filter(address => address.id !== editingId)); setEditingId(null); }}>Xóa địa chỉ</button>}</div></form>; };
  const chooseAddress = id => { setSelectedAddressId(id); setAddressOpen(false); };
